24     template<typename T>
25     GLM_FUNC_QUALIFIER T mask(T Bits)
26     {
27         return Bits >= static_cast<T>(sizeof(T) * 8) ? ~static_cast<T>(0) : (static_cast<T>(1) << Bits) - static_cast<T>(1);
28     }
29 
30     template<length_t L, typename T, qualifier Q, bool Aligned, bool EXEC>
31     struct compute_bitfieldReverseStep
32     {
33         GLM_FUNC_QUALIFIER static vec<L, T, Q> call(vec<L, T, Q> const& v, T, T)
34         {
35             return v;
36         }
37     };
38 
39     template<length_t L, typename T, qualifier Q, bool Aligned>
40     struct compute_bitfieldReverseStep<L, T, Q, Aligned, true>
41     {
42         GLM_FUNC_QUALIFIER static vec<L, T, Q> call(vec<L, T, Q> const& v, T Mask, T Shift)
43         {
44             return (v & Mask) << Shift | (v & (~Mask)) >> Shift;
45         }
46     };
47 
48     template<length_t L, typename T, qualifier Q, bool Aligned, bool EXEC>
49     struct compute_bitfieldBitCountStep
50     {
51         GLM_FUNC_QUALIFIER static vec<L, T, Q> call(vec<L, T, Q> const& v, T, T)
52         {
53             return v;
54         }
55     };
56 
57     template<length_t L, typename T, qualifier Q, bool Aligned>
58     struct compute_bitfieldBitCountStep<L, T, Q, Aligned, true>
59     {
60         GLM_FUNC_QUALIFIER static vec<L, T, Q> call(vec<L, T, Q> const& v, T Mask, T Shift)
61         {
62             return (v & Mask) + ((v >> Shift) & Mask);
63         }
64     };
