66     template<typename genIUType, size_t Bits>
67     struct compute_findLSB
68     {
69         GLM_FUNC_QUALIFIER static int call(genIUType Value)
70         {
71             if(Value == 0)
72                 return -1;
73 
74             return glm::bitCount(~Value & (Value - static_cast<genIUType>(1)));
75         }
76     };
