104     template<length_t L, typename T, qualifier Q, bool EXEC = true>
105     struct compute_findMSB_step_vec
106     {
107         GLM_FUNC_QUALIFIER static vec<L, T, Q> call(vec<L, T, Q> const& x, T Shift)
108         {
109             return x | (x >> Shift);
110         }
111     };
112 
113     template<length_t L, typename T, qualifier Q>
114     struct compute_findMSB_step_vec<L, T, Q, false>
115     {
116         GLM_FUNC_QUALIFIER static vec<L, T, Q> call(vec<L, T, Q> const& x, T)
117         {
118             return x;
119         }
120     };
121 
122     template<length_t L, typename T, qualifier Q, int>
123     struct compute_findMSB_vec
124     {
125         GLM_FUNC_QUALIFIER static vec<L, int, Q> call(vec<L, T, Q> const& v)
126         {
127             vec<L, T, Q> x(v);
128             x = compute_findMSB_step_vec<L, T, Q, sizeof(T) * 8 >=  8>::call(x, static_cast<T>( 1));
129             x = compute_findMSB_step_vec<L, T, Q, sizeof(T) * 8 >=  8>::call(x, static_cast<T>( 2));
130             x = compute_findMSB_step_vec<L, T, Q, sizeof(T) * 8 >=  8>::call(x, static_cast<T>( 4));
131             x = compute_findMSB_step_vec<L, T, Q, sizeof(T) * 8 >= 16>::call(x, static_cast<T>( 8));
132             x = compute_findMSB_step_vec<L, T, Q, sizeof(T) * 8 >= 32>::call(x, static_cast<T>(16));
133             x = compute_findMSB_step_vec<L, T, Q, sizeof(T) * 8 >= 64>::call(x, static_cast<T>(32));
134             return vec<L, int, Q>(sizeof(T) * 8 - 1) - glm::bitCount(~x);
135         }
136     };
