177     // uaddCarry
178     GLM_FUNC_QUALIFIER uint uaddCarry(uint const& x, uint const& y, uint & Carry)
179     {
180         detail::uint64 const Value64(static_cast<detail::uint64>(x) + static_cast<detail::uint64>(y));
181         detail::uint64 const Max32((static_cast<detail::uint64>(1) << static_cast<detail::uint64>(32)) - static_cast<detail::uint64>(1));
182         Carry = Value64 > Max32 ? 1u : 0u;
183         return static_cast<uint>(Value64 % (Max32 + static_cast<detail::uint64>(1)));
184     }
185 
186     template<length_t L, qualifier Q>
187     GLM_FUNC_QUALIFIER vec<L, uint, Q> uaddCarry(vec<L, uint, Q> const& x, vec<L, uint, Q> const& y, vec<L, uint, Q>& Carry)
188     {
189         vec<L, detail::uint64, Q> Value64(vec<L, detail::uint64, Q>(x) + vec<L, detail::uint64, Q>(y));
190         vec<L, detail::uint64, Q> Max32((static_cast<detail::uint64>(1) << static_cast<detail::uint64>(32)) - static_cast<detail::uint64>(1));
191         Carry = mix(vec<L, uint, Q>(0), vec<L, uint, Q>(1), greaterThan(Value64, Max32));
192         return vec<L, uint, Q>(Value64 % (Max32 + static_cast<detail::uint64>(1)));
193     }
