195     // usubBorrow
196     GLM_FUNC_QUALIFIER uint usubBorrow(uint const& x, uint const& y, uint & Borrow)
197     {
198         Borrow = x >= y ? static_cast<uint>(0) : static_cast<uint>(1);
199         if(y >= x)
200             return y - x;
201         else
202             return static_cast<uint>((static_cast<detail::int64>(1) << static_cast<detail::int64>(32)) + (static_cast<detail::int64>(y) - static_cast<detail::int64>(x)));
203     }
204 
205     template<length_t L, qualifier Q>
206     GLM_FUNC_QUALIFIER vec<L, uint, Q> usubBorrow(vec<L, uint, Q> const& x, vec<L, uint, Q> const& y, vec<L, uint, Q>& Borrow)
207     {
208         Borrow = mix(vec<L, uint, Q>(1), vec<L, uint, Q>(0), greaterThanEqual(x, y));
209         vec<L, uint, Q> const YgeX(y - x);
210         vec<L, uint, Q> const XgeY(vec<L, uint, Q>((static_cast<detail::int64>(1) << static_cast<detail::int64>(32)) + (vec<L, detail::int64, Q>(y) - vec<L, detail::int64, Q>(x))));
211         return mix(XgeY, YgeX, greaterThanEqual(y, x));
212     }
