214     // umulExtended
215     GLM_FUNC_QUALIFIER void umulExtended(uint const& x, uint const& y, uint & msb, uint & lsb)
216     {
217         detail::uint64 Value64 = static_cast<detail::uint64>(x) * static_cast<detail::uint64>(y);
218         msb = static_cast<uint>(Value64 >> static_cast<detail::uint64>(32));
219         lsb = static_cast<uint>(Value64);
220     }
