222     template<length_t L, qualifier Q>
223     GLM_FUNC_QUALIFIER void umulExtended(vec<L, uint, Q> const& x, vec<L, uint, Q> const& y, vec<L, uint, Q>& msb, vec<L, uint, Q>& lsb)
224     {
225         vec<L, detail::uint64, Q> Value64(vec<L, detail::uint64, Q>(x) * vec<L, detail::uint64, Q>(y));
226         msb = vec<L, uint, Q>(Value64 >> static_cast<detail::uint64>(32));
227         lsb = vec<L, uint, Q>(Value64);
228     }
