230     // imulExtended
231     GLM_FUNC_QUALIFIER void imulExtended(int x, int y, int& msb, int& lsb)
232     {
233         detail::int64 Value64 = static_cast<detail::int64>(x) * static_cast<detail::int64>(y);
234         msb = static_cast<int>(Value64 >> static_cast<detail::int64>(32));
235         lsb = static_cast<int>(Value64);
