246     // bitfieldExtract
247     template<typename genIUType>
248     GLM_FUNC_QUALIFIER genIUType bitfieldExtract(genIUType Value, int Offset, int Bits)
249     {
250         return bitfieldExtract(vec<1, genIUType>(Value), Offset, Bits).x;
251     }
252 
253     template<length_t L, typename T, qualifier Q>
254     GLM_FUNC_QUALIFIER vec<L, T, Q> bitfieldExtract(vec<L, T, Q> const& Value, int Offset, int Bits)
255     {
256         GLM_STATIC_ASSERT(std::numeric_limits<T>::is_integer, "'bitfieldExtract' only accept integer inputs");
257 
258         return (Value >> static_cast<T>(Offset)) & static_cast<T>(detail::mask(Bits));
259     }
260 
261     // bitfieldInsert
262     template<typename genIUType>
263     GLM_FUNC_QUALIFIER genIUType bitfieldInsert(genIUType const& Base, genIUType const& Insert, int Offset, int Bits)
264     {
265         GLM_STATIC_ASSERT(std::numeric_limits<genIUType>::is_integer, "'bitfieldInsert' only accept integer values");
266 
267         return bitfieldInsert(vec<1, genIUType>(Base), vec<1, genIUType>(Insert), Offset, Bits).x;
268     }
269 
270     template<length_t L, typename T, qualifier Q>
271     GLM_FUNC_QUALIFIER vec<L, T, Q> bitfieldInsert(vec<L, T, Q> const& Base, vec<L, T, Q> const& Insert, int Offset, int Bits)
272     {
273         GLM_STATIC_ASSERT(std::numeric_limits<T>::is_integer, "'bitfieldInsert' only accept integer values");
274 
275         T const Mask = detail::mask(static_cast<T>(Bits)) << Offset;
276         return (Base & ~Mask) | ((Insert << static_cast<T>(Offset)) & Mask);
277     }
