345     // findLSB
346     template<typename genIUType>
347     GLM_FUNC_QUALIFIER int findLSB(genIUType Value)
348     {
349         GLM_STATIC_ASSERT(std::numeric_limits<genIUType>::is_integer, "'findLSB' only accept integer values");
350 
351         return detail::compute_findLSB<genIUType, sizeof(genIUType) * 8>::call(Value);
352     }
