354     template<length_t L, typename T, qualifier Q>
355     GLM_FUNC_QUALIFIER vec<L, int, Q> findLSB(vec<L, T, Q> const& x)
356     {
357         GLM_STATIC_ASSERT(std::numeric_limits<T>::is_integer, "'findLSB' only accept integer values");
358 
359         return detail::functor1<vec, L, int, T, Q>::call(findLSB, x);
360     }
